#!/bin/bash
# Downloads DW Top-Thema audio for the Lesen & Hören update (2026-10-22).
# Run from anywhere: bash "<project>/_factory/listening/download-audio.sh"
set -u
cd "$(dirname "$0")/../../content/listening/articles" || exit 1
ok=0; fail=0
get() { if [ -s "$1/audio.mp3" ]; then echo "skip $1"; ok=$((ok+1)); return; fi
  if curl -fsSL --retry 3 -o "$1/audio.mp3.part" "$2" && mv "$1/audio.mp3.part" "$1/audio.mp3"; then echo "ok   $1"; ok=$((ok+1)); else echo "FAIL $1"; rm -f "$1/audio.mp3.part"; fail=$((fail+1)); fi; }
